(() => {
'use strict';
const $=id=>document.getElementById(id), canvas=$('scene'),ctx=canvas.getContext('2d');
ctx.imageSmoothingEnabled=false;
const TILE=32, W=20,H=12;
const game={mode:'intro',started:false,map:'village',player:{x:4,y:7,face:'down',hp:32,maxHp:32,mp:12,maxMp:12,level:1,exp:0,gil:0,shards:0,atk:7,def:4},party:[],inventory:{'Moonberry tonic':2,'Taming shard':2},flags:{metGuide:false,woodsOpen:false,groveBoss:false,castleOpen:false,ending:false},steps:0,battle:null,dialogue:[],dialogueDone:null,selected:0,sound:false};
const maps={village:{name:'DUSKBRIAR VILLAGE',hint:'Someone here may know what happened.',theme:'village',exits:[{x:19,y:5,to:'forest',tx:1,ty:5,need:null}]},forest:{name:'THE HOLLOWMERE',hint:'Find the old shrine to the east.',theme:'forest',exits:[{x:0,y:5,to:'village',tx:18,ty:5},{x:19,y:5,to:'castle',tx:1,ty:6,need:'castleOpen'}]},castle:{name:'THRONE OF ASH',hint:'The old king is waiting above.',theme:'castle',exits:[{x:0,y:6,to:'forest',tx:18,ty:5}]}};
const monsterData={wisp:{name:'Moss Wisp',icon:'☼',hp:15,maxHp:15,atk:4,def:1,skill:'Sporelight',color:'#b8d982'},bat:{name:'Gloam Bat',icon:'⌁',hp:20,maxHp:20,atk:5,def:2,skill:'Screech',color:'#c18fc8'},wolf:{name:'Ashen Pup',icon:'♧',hp:25,maxHp:25,atk:6,def:2,skill:'Cinder Pounce',color:'#df9d76'}};
const encounters={forest:['wisp','bat','wolf']};
let toastTimer;
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function rand(n){return Math.floor(Math.random()*n)}
function showToast(t){const el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function setMode(m){game.mode=m; $('battle-panel').classList.toggle('hidden',m!=='battle');$('dialogue-box').classList.toggle('hidden',m!=='dialogue');}
function startGame(){game.started=true;$('intro-screen').classList.add('hidden');$('location-name').textContent=maps.village.name;showDialogue([{speaker:'SYSTEM',avatar:'▣',text:'Consciousness restored. Soul status: abnormal. Species: vampire. Welcome to Veyra, Rin.'},{speaker:'SYSTEM',avatar:'▣',text:'PRIMARY OBJECTIVE: Become the Demon King. Secondary directive: survive long enough to understand why.'},{speaker:'RIN',avatar:'✦',text:'I was an ordinary girl five minutes ago. I am absolutely not qualified to be anyone’s Demon King.'},{speaker:'SYSTEM',avatar:'▣',text:'Qualification is not required. Progress is. Seek the village guide. Your new life begins now.'}],()=>{game.flags.started=true;setMode('world');updateUI();draw()})}
function showDialogue(lines,done){game.dialogue=lines.map(x=>({...x}));game.dialogueDone=done||null;setMode('dialogue');nextDialogue()}
function nextDialogue(){if(game.mode!=='dialogue')return;const line=game.dialogue.shift();if(!line){$('dialogue-box').classList.add('hidden');if(game.dialogueDone){const done=game.dialogueDone;game.dialogueDone=null;done()}else setMode('world');return}$('dialogue-speaker').textContent=line.speaker;$('dialogue-avatar').textContent=line.avatar||'✦';$('dialogue-text').textContent=line.text}
function updateUI(){const p=game.player;$('hero-level').textContent=p.level;$('hero-hp').textContent=`${p.hp} / ${p.maxHp}`;$('hero-mp').textContent=`${p.mp} / ${p.maxMp}`;$('hero-hp-fill').style.width=`${100*p.hp/p.maxHp}%`;$('hero-mp-fill').style.width=`${100*p.mp/p.maxMp}%`;$('hero-atk').textContent=p.atk;$('hero-def').textContent=p.def;$('hero-gil').textContent=p.gil;$('hero-shards').textContent=p.shards;$('hero-exp').textContent=`${p.exp}/${p.level*20}`;$('exp-fill').style.width=`${100*p.exp/(p.level*20)}%`;
 const objectives=[['A crown in the dark','Meet the village guide in Duskbriar.','PROLOGUE',10],['A heart to call your own','Tame a creature in the Hollowmere.','CHAPTER 01 · THE HOLLOWMERE',32],['The shrine remembers','Defeat the Warden at the old shrine.','CHAPTER 01 · THE HOLLOWMERE',62],['A throne without a king','Defeat the Ashen Regent. Claim your fate.','CHAPTER 02 · THRONE OF ASH',88],['The new Demon King','You have changed the meaning of the crown.','EPILOGUE · A NEW DAWN',100]];
 let n=game.flags.ending?4:game.flags.groveBoss?3:game.flags.metGuide&&game.party.length?2:game.flags.metGuide?1:0;let q=objectives[n];$('quest-title').textContent=q[0];$('quest-description').textContent=q[1];$('quest-progress-label').textContent=q[2];$('quest-progress').style.width=q[3]+'%';$('chapter-label').textContent=q[2];$('party-count').textContent=`${game.party.length+1} / 03`;
 const list=$('party-list');list.innerHTML=`<div class="party-member"><div class="member-emblem">✦</div><div class="member-data"><div class="member-title"><span>Rin</span><small>LV ${p.level} · VAMPIRE</small></div><div class="member-health"><i style="width:${100*p.hp/p.maxHp}%"></i></div></div></div>`+game.party.map(m=>`<div class="party-member"><div class="member-emblem" style="color:${m.color}">${m.icon}</div><div class="member-data"><div class="member-title"><span>${m.name}</span><small>LV ${m.level||1} · ${m.hp}/${m.maxHp}</small></div><div class="member-health"><i style="width:${100*m.hp/m.maxHp}%"></i></div></div></div>`).join('')+(game.party.length?'':'<div class="member-empty">No familiars yet. The wild can be persuaded.</div>');
 const inv=$('inventory-list');inv.innerHTML=Object.entries(game.inventory).filter(([,v])=>v>0).map(([k,v])=>`<span class="inventory-chip">${k==='Moonberry tonic'?'✧':'◇'} ${k}<b>×${v}</b></span>`).join('')||'<span class="inventory-chip">Empty</span>';
 $('world-hint').textContent=maps[game.map].hint;$('location-name').textContent=maps[game.map].name;$('time-label').textContent=game.map==='village'?'LAST LIGHT':game.map==='forest'?'MOONLIT':'MIDNIGHT';draw();}

