$('world-hint').textContent=maps[game.map].hint;$('location-name').textContent=maps[game.map].name;$('time-label').textContent=game.map==='village'?'LAST LIGHT':game.map==='forest'?'MOONLIT':'MIDNIGHT';draw();}
function box(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function hash(x,y){let v=Math.sin(x*127.1+y*311.7)*43758.5453;return v-Math.floor(v)}
function drawGround(){const theme=maps[game.map].theme;let base=theme==='village'?'#3c5945':theme==='forest'?'#263c37':'#373442',path=theme==='village'?'#71624f':theme==='forest'?'#52604a':'#5c5260';box(0,0,640,400,base);
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let px=x*TILE,py=y*TILE,r=hash(x,y);let road=theme==='village'?(y>=5&&y<=6||x>=8&&x<=9&&y>2):theme==='forest'?(y===5||x===10&&y>5&&y<10):x>8&&y>4&&y<8;let isPath=road;
 if(theme==='forest'&&(x>12&&y>3&&y<8))isPath=true;if(theme==='castle'&&x>=10&&y>=4&&y<=7)isPath=true;
 box(px,py,TILE,TILE,isPath?path:base);if(isPath){box(px+2,py+4,3,2,theme==='castle'?'#746878':'#89715a');if(r>.6)box(px+18,py+23,4,2,'#443f3c')}else{box(px+3+Math.floor(r*19),py+4+Math.floor(hash(y,x)*22),2,3,theme==='castle'?'#514c5c':theme==='forest'?'#354e40':'#49674d');if(r>.8)box(px+22,py+9,3,2,theme==='forest'?'#6a8050':'#6d7950')}
 }
 if(theme==='village'){
  building(2,1,4,3,'#554353','#96745f','INN');building(11,1,5,3,'#473c4e','#80705f','CHAPEL');
  box(0,0,640,3,'#211d2b');box(0,0,8,400,'#283646');box(632,0,8,400,'#283646');
  for(let x=1;x<20;x+=2){box(x*32+15,153,3,4,'#e6c982');box(x*32+14,157,5,5,'#aa785d')}
  drawNpc(8,6,'guide');drawNpc(4,5,'healer');drawSign(6,8);
 }else if(theme==='forest'){
  // tree wall and scattered hollow trees
  for(let y=0;y<H;y++){tree(0,y);tree(19,y)}for(let x=1;x<19;x++){tree(x,0);tree(x,11)}
  [[3,2],[5,2],[3,3],[6,2],[13,2],[15,2],[17,2],[2,8],[4,9],[7,8],[12,9],[14,9],[17,9],[5,6],[12,3]].forEach(a=>tree(a[0],a[1]));
  drawShrine();drawNpc(7,7,'scout');
 }else{
  // castle walls, banners and long throne aisle
  box(2*32,32,14*32,3*32,'#443d4f');box(2*32+4,36,14*32-8,3*32-8,'#5b5260');
  for(let x=3;x<16;x+=2){box(x*32,31,32,10,'#897a84');box(x*32+11,48,10,37,'#4e4656');box(x*32+13,52,6,6,'#edc586')}
  for(let y=2;y<10;y++){box(2*32,y*32,12,31,'#64576a');box(17*32,y*32,12,31,'#64576a')}
  box(2*32,2*32,12,10,'#8e7080');box(17*32,2*32,12,10,'#8e7080');drawNpc(15,5,'regent');
 }
}
