function draw(){if(!ctx)return;drawGround();if(game.mode==='battle'&&game.battle){drawBattleScene()}else{drawHero();if(game.mode==='world'){for(const e of maps[game.map].exits)if(e.need&&!game.flags[e.need]){box(e.x*TILE,e.y*TILE,32,32,'#281e3588');box(e.x*TILE+11,e.y*TILE+5,10,22,'#ac668e');box(e.x*TILE+14,e.y*TILE+9,4,14,'#e3b3c9')}}} }
function drawBattleScene(){const b=game.battle;box(0,0,640,400,'#1514217a');box(0,280,640,120,'#11101aaa');for(let i=0;i<9;i++)box(i*80,313+(i%2)*5,64,3,'#63546966');drawCreature(426,212,b.enemy.key,true);sprite(142,313,'#d6a8c6','#9b3c60','#e8c9c2','#473449');game.party.forEach((m,i)=>drawCreature(190+i*45,305,m.key,false));}
function beginBattle(key,boss=null){const d=monsterData[key],isBoss=!!boss;let hp=isBoss?(boss==='warden'?68:112):d.hp+Math.max(0,game.player.level-1)*4;let enemy={key,name:isBoss?boss==='warden'?'SHRINE WARDEN':'ASHEN REGENT':d.name,hp,maxHp:hp,atk:isBoss?boss==='warden'?9:12:d.atk+Math.max(0,game.player.level-1),def:isBoss?3:d.def,level:isBoss?Math.max(3,game.player.level+2):Math.max(1,game.player.level),boss};game.battle={enemy,guard:false,locked:false,won:false};game.selected=0;setMode('battle');$('battle-log').textContent=isBoss?(boss==='warden'?'The shrine’s ancient guardian rises.':'The Ashen Regent draws the last of his flame.'):`A wild ${d.name} appears!`;renderBattle();draw();}
function renderBattle(){if(!game.battle)return;const e=game.battle.enemy,percent=Math.max(0,100*e.hp/e.maxHp);$('enemy-name').textContent=e.name;$('enemy-level').textContent=`LV ${e.level}`;$('enemy-hp-fill').style.width=percent+'%';$('enemy-hp-text').textContent=`${Math.max(0,e.hp)} / ${e.maxHp}`;$('battle-party').innerHTML=game.party.map(m=>`<span>${m.icon} ${m.name}<i>${m.hp}/${m.maxHp}</i></span>`).join('');const actions=$('battle-actions');actions.innerHTML='';$('battle-submenu').classList.add('hidden');$('battle-submenu').innerHTML='';if(game.battle.locked)return;
 const opts=[['ATTACK','',()=>playerAction('attack')],['BLOOD SIPHON','4 MP',()=>playerAction('siphon')],['TAME','◇ '+(game.inventory['Taming shard']||0),()=>playerAction('tame')],['GUARD','',()=>playerAction('guard')]];opts.forEach(([label,cost,fn])=>{const btn=document.createElement('button');btn.className='battle-action';btn.innerHTML=`${label}<span>${cost}</span>`;if(label==='BLOOD SIPHON'&&game.player.mp<4)btn.disabled=true;if(label==='TAME'&&(game.inventory['Taming shard']||0)<1||e.boss)btn.disabled=true;btn.onclick=fn;actions.appendChild(btn)});}
function battleLog(text){$('battle-log').textContent=text;}
function playerAction(action){const b=game.battle;if(!b||b.locked)return;b.locked=true;let e=b.enemy,p=game.player,log='';if(action==='attack'){let damage=Math.max(1,p.atk+rand(4)-e.def);e.hp-=damage;log=`Rin strikes for ${damage} damage!`}
 if(action==='siphon'){if(p.mp<4){b.locked=false;return}p.mp-=4;let damage=10+rand(5)+p.level*2-e.def;e.hp-=Math.max(3,damage);let heal=Math.min(p.maxHp-p.hp,Math.ceil(damage*.42));p.hp+=heal;log=`Blood Siphon deals ${Math.max(3,damage)} and restores ${heal} HP.`}
 if(action==='guard'){b.guard=true;log='Rin braces for the next attack.'}
 if(action==='tame'){const shards=game.inventory['Taming shard']||0;if(!shards){b.locked=false;showToast('No Taming Shards left!');renderBattle();return}game.inventory['Taming shard']--;let chance=e.hp/e.maxHp<.35?.82:e.hp/e.maxHp<.65?.57:.25;if(e.boss)chance=0;if(Math.random()<chance&&game.party.length<2){game.party.push({...monsterData[e.key],key:e.key,level:1});updateUI();battleLog(`${monsterData[e.key].name} accepted your pact! It joins your coven.`);renderBattle();setTimeout(()=>victory(true),800);return}else if(game.party.length>=2){log='Your coven is full. The creature slips free!'}else{log='The shard glows—but the creature resists your pact!'}}
 battleLog(log);renderBattle();draw();updateUI();if(e.hp<=0){setTimeout(()=>victory(false),480);return}setTimeout(enemyTurn,550);}
function enemyTurn(){const b=game.battle;if(!b)return;const e=b.enemy,p=game.player;if(game.party.length&&Math.random()<.78){const m=game.party[rand(game.party.length)];if(m.hp>0){let dmg=Math.max(2,4+m.level+rand(4)-e.def);e.hp-=dmg;battleLog(`${m.name} uses ${m.skill}! ${dmg} damage.`);renderBattle();draw();if(e.hp<=0){setTimeout(()=>victory(false),450);return}}}
