function distance(x,y,a,b){return Math.abs(x-a)+Math.abs(y-b)}
function blocked(x,y){if(x<0||x>=W||y<0||y>=H)return true;const theme=maps[game.map].theme;if(theme==='village'&&((x>=2&&x<=5&&y>=1&&y<=3)||(x>=11&&x<=15&&y>=1&&y<=3)))return true;
 if(theme==='forest'){const trees=[[3,2],[5,2],[3,3],[6,2],[13,2],[15,2],[17,2],[2,8],[4,9],[7,8],[12,9],[14,9],[17,9],[5,6],[12,3]];if(x===0||x===19||y===0||y===11||trees.some(a=>a[0]===x&&a[1]===y))return true;}
 if(theme==='castle'&&(x<=2||x>=17||y<=1||y>=10))return true;return false;}
function move(dx,dy){if(game.mode!=='world')return;const p=game.player,nx=p.x+dx,ny=p.y+dy;p.face=dx<0?'left':dx>0?'right':dy<0?'up':'down';if(blocked(nx,ny))return;
 const exit=maps[game.map].exits.find(e=>e.x===nx&&e.y===ny);if(exit){if(exit.need&&!game.flags[exit.need]){showToast(game.map==='forest'?'A presence seals the castle path.':'The path is locked.');return}game.map=exit.to;p.x=exit.tx;p.y=exit.ty;updateUI();showToast(maps[game.map].name);return}
 p.x=nx;p.y=ny;game.steps++;draw();if(game.map==='forest'&&game.steps>3&&Math.random()<.16){const key=encounters.forest[rand(encounters.forest.length)];beginBattle(key)} }
function interact(){if(game.mode!=='world')return;const p=game.player;
 if(game.map==='village'){
  if(distance(p.x,p.y,8,6)<=2){if(!game.flags.metGuide){game.flags.metGuide=true;game.inventory['Taming shard']+=2;game.player.hp=game.player.maxHp;game.player.mp=game.player.maxMp;updateUI();showDialogue([{speaker:'MARA · VILLAGE GUIDE',avatar:'♧',text:'A vampire, and a stranger besides. I am Mara. You have the look of someone who woke up in the wrong story.'},{speaker:'RIN',avatar:'✦',text:'That is… extremely accurate. There is a voice in my head telling me to become the Demon King.'},{speaker:'MARA · VILLAGE GUIDE',avatar:'♧',text:'Then you’ll need allies. The wild things in Hollowmere can form a pact with you. Weave a Taming Shard around a creature when it is weakened.'},{speaker:'MARA · VILLAGE GUIDE',avatar:'♧',text:'Take these two shards. Find a familiar, then follow the old path east. The shrine’s guardian may know why you were called here.'}],()=>setMode('world'))}else showDialogue([{speaker:'MARA · VILLAGE GUIDE',avatar:'♧',text:'Hollowmere lies east. Soften a wild creature before offering your shard; a frightened heart is harder to reach.'}],()=>setMode('world'));return}
  if(distance(p.x,p.y,4,5)<=1){openHealer();return}if(distance(p.x,p.y,6,8)<=1){showDialogue([{speaker:'SIGN',avatar:'▤',text:'DUSKBRIAR — Last village before the Hollowmere. Stay on the old road after sunset.'}],()=>setMode('world'));return}
  showToast('Nothing answers from here.');return}
 if(game.map==='forest'){
  if(distance(p.x,p.y,7,7)<=1){showDialogue([{speaker:'ELI · TRAIL SCOUT',avatar:'♧',text:'The shrine is east, past the silver stones. I’ve seen a wisp make a pact with a lost traveler. The shard works best when your foe is near defeat.'}],()=>setMode('world'));return}
  if(distance(p.x,p.y,16,5)<=2){if(!game.flags.groveBoss){if(!game.party.length){showToast('The shrine hums. A familiar would make this safer.');return}beginBattle('wolf','warden')}else{showDialogue([{speaker:'SYSTEM',avatar:'▣',text:'The shrine’s sigil is quiet now. A road has opened toward the throne of ash.'}],()=>setMode('world'))}return}
  showToast('The dark is listening.');return}
